    fclose(f);
    unsigned char* dev;
    CUDA_CHECK(cudaMalloc(&dev, count));
    CUDA_CHECK(cudaMemcpy(dev, host, count, cudaMemcpyHostToDevice));
    free(host);
    return dev;
}

